/* Shared header, menu and footer for every page.
   Edit the text/links here once and all pages update.
   IMPORTANT: load this file right after <body> with NO defer:
   <script src="nav.js"></script> */
(function () {
  var headerHTML = `
<header class="top" id="top">
  <a class="pendant-link" href="index.html" aria-label="Home">
    <svg class="pendant" viewBox="0 0 675 565" aria-hidden="true">
      <image href="data:image/png;base64," width="675" height="565"/>
      <text x="153" y="462" text-anchor="middle">A</text>
      <text x="388" y="428" text-anchor="middle">R</text>
    </svg>
  </a>

  <button class="burger" id="burger" aria-label="Open menu" aria-expanded="false" aria-controls="menu">
    <span></span><span></span>
  </button>
</header>

<nav class="menu" id="menu">
  <a href="index.html">Home</a>
  <a href="schedule.html">Schedule</a>
  <a href="gallery.html">Gallery</a>
  <a class="pill-btn" href="rsvp.html">RSVP</a>
</nav>`;

  var footerHTML = `
<footer class="site-footer">
  <div class="foot-info">
   
    <div class="foot-col">
      <h2>Date</h2>
      <p>November 19 &ndash; 21, 2026</p>
    </div>
    <div class="foot-col">
      <h2>RSVP</h2>
      <p>We'd love to know if you can join us for our special day. Kindly let us know your response.<br>Thank you!</p>
      <a class="foot-link" href="rsvp.html">RSVP here</a>
    </div>
    <div class="foot-col">
      <h2>Contact</h2>
      <p>For any questions, feel free to reach out to us on Instagram.</p>
      <p>@rupalihansda26</p>
      <p>@chillyguy.amal</p>

    </div>

  </div>
  <div class="foot-initials"><img src="data:image/png;base64," alt="A and R" class="monogram"></div>
</footer>`;

  /* The header is added at once, so the page never jumps when it loads. */
  document.body.insertAdjacentHTML('afterbegin', headerHTML);

  /* The footer is added when the rest of the page has been read. */
  function addFooter() {
    document.body.insertAdjacentHTML('beforeend', footerHTML);
  }
  if (document.readyState === 'loading') {
    document.addEventListener('DOMContentLoaded', addFooter);
  } else {
    addFooter();
  }

  var burger = document.getElementById('burger');
  var menu = document.getElementById('menu');

  function setMenu(open) {
    document.body.classList.toggle('menu-open', open);
    burger.setAttribute('aria-expanded', open);
    burger.setAttribute('aria-label', open ? 'Close menu' : 'Open menu');
  }

  burger.addEventListener('click', function () {
    setMenu(!document.body.classList.contains('menu-open'));
  });
  menu.querySelectorAll('a').forEach(function (a) {
    a.addEventListener('click', function (e) {
      var wasOpen = document.body.classList.contains('menu-open');
      setMenu(false);
      /* phone menu: let it fade out first, then go to the page */
      if (wasOpen && !e.ctrlKey && !e.metaKey && !e.shiftKey && a.getAttribute('href').charAt(0) !== '#') {
        e.preventDefault();
        setTimeout(function () { window.location.href = a.href; }, 280);
      }
    });
  });
  document.addEventListener('keydown', function (e) {
    if (e.key === 'Escape') setMenu(false);
  });
  window.addEventListener('resize', function () {
    if (window.innerWidth >= 900) setMenu(false);
  });
})();